lityObject.onUseAbility = function(player, target, ability, action)\n    xi.job_utils.dragoon.useSmitingBreath(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/snake_eye.lua"]={["Path"]="scripts/actions/abilities/snake_eye.lua",["SHA256"]="cc4ec0532016cf8aec026c64c755adc37b961a9b1e8824b866a6c8c2838d0117",["Text"]="-----------------------------------\n-- Ability: Snake Eye\n-- Your next roll will automatically be a 1.\n-- Obtained: Corsair Level 75\n-- Recast Time: 0:05:00\n-- Duration: 0:01:00 or the next usage of Phantom Roll or Double-Up\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.corsair.useSnakeEye(player, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/snarl.lua"]={["Path"]="scripts/actions/abilities/snarl.lua",["SHA256"]="76aebd5b24b4b6e1c672d1df068c3b4f78854bc613d64bde9d85a669073be49a",["Text"]="-----------------------------------\n-- Ability: Snarl\n-- Transfers hate to your pet. Only works on pets invoked with the \"Call Beast\" ability.\n-- Obtained: Beastmaster Level 45\n-- Recast Time: 30 seconds\n-- Duration: N/A\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkSnarl(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.beastmaster.useSnarl(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/sneak_attack.lua"]={["Path"]="scripts/actions/abilities/sneak_attack.lua",["SHA256"]="a4f2ae58f72abf7575000d00e456ec511addd5fb9c4b1169fa9627bd16723538",["Text"]="-----------------------------------\n-- Ability: Sneak Attack\n-- Deals critical damage when striking from behind.\n-- Obtained: Thief Level 15\n-- Recast Time: 1:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.thief.useSneakAttack(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/soul_enslavement.lua"]={["Path"]="scripts/actions/abilities/soul_enslavement.lua",["SHA256"]="40f7a3394188e3fe0d2be0b66784674b7c70710a2c398f94a39e64811ab9c211",["Text"]="-----------------------------------\n-- Ability: Soul Enslavement\n-- Description: Melee attacks absorb target's TP.\n-- Obtained: Dark Knight Level 96\n-- Recast Time: 01:00:00\n-- Duration: 00:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dark_knight.checkSoulEnslavement(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dark_knight.useSoulEnslavement(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/soul_jump.lua"]={["Path"]="scripts/actions/abilities/soul_jump.lua",["SHA256"]="a7edbad71982eff5c7ac6cf0105158aad560161081d69ea5465d7c931e0e34e8",["Text"]="-----------------------------------\n-- Ability: Soul Jump\n-- Description: Delivers a high jumping attack on a targeted enemy which suppresses enmity. Effect enhanced when wyvern is present.\n-- Obtained: DRG Level 85\n-- Recast Time: 2:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dragoon.useSoulJump(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/soul_voice.lua"]={["Path"]="scripts/actions/abilities/soul_voice.lua",["SHA256"]="0f7e93408cbea71bc8f39aed9c2cddc1dd371f8e7a1e0cde1d89ebbc5c7c3328",["Text"]="-----------------------------------\n-- Ability: Soul Voice\n-- Enhances the effects of your songs.\n-- Obtained: Bard Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.bard.checkSoulVoice(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.bard.useSoulVoice(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/souleater.lua"]={["Path"]="scripts/actions/abilities/souleater.lua",["SHA256"]="cbeb813812a2aedecb5081135dc64ecf2ae8e3e571a68bea4987676e5f009243",["Text"]="-----------------------------------\n-- Ability: Souleater\n-- Description: Consumes your own HP to enhance attacks.\n-- Obtained: Dark Knight Level 30\n-- Recast Time: 00:06:00\n-- Duration: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dark_knight.useSouleater(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/spectral_jig.lua"]={["Path"]="scripts/actions/abilities/spectral_jig.lua",["SHA256"]="0a6244847f604eff4ad439f437258608d005d7cfd998059a15d4ada13f408559",["Text"]="-----------------------------------\n-- Ability: Spectral jig\n-- Allows you to evade enemies by making you undetectable by sight and sound.\n-- Obtained: Dancer Level 25\n-- TP Required: 0\n-- Recast Time: 30 seconds\n-- Duration: 3 minutes\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    local baseDuration       = 180 + player:getJobPointLevel(xi.jp.JIG_DURATION)\n    local durationMultiplier = 1.0 + utils.clamp(player:getMod(xi.mod.JIG_DURATION), 0, 50) / 100\n    local finalDuration      = math.floor(baseDuration * durationMultiplier * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER)\n\n    if not player:hasStatusEffect(xi.effect.SNEAK) then\n        player:addStatusEffect(xi.effect.SNEAK, { duration = finalDuration, origin = player, tick = 10 })\n        player:addStatusEffect(xi.effect.INVISIBLE, { duration = finalDuration, origin = player, tick = 10 })\n        ability:setMsg(xi.msg.basic.SPECTRAL_JIG) -- Gains the effect of sneak and invisible\n    else\n        ability:setMsg(xi.msg.basic.NO_EFFECT) -- no effect on player.\n    end\n\n    return 1\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/spirit_bond.lua"]={["Path"]="scripts/actions/abilities/spirit_bond.lua",["SHA256"]="1674000ea28a8bde75de6a49f13f05c37637f0b8fcfde430c5b7ea3453be8e25",["Text"]="-----------------------------------\n-- Ability: Spirit Bond\n-- Description: Enables the dragoon to take some damage on behalf of their wyvern. Using Healing Breath also restores the wyvern's HP.\n-- Obtained: DRG Level 65\n-- Recast Time: 00:03:00\n-- Duration: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dragoon.abilityCheckRequiresPet(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dragoon.useSpiritBond(player, target, ability)\nend\n\nreturn abilityObject\n"}};
